from pathlib import Path
import hashlib,json,statistics,xml.etree.ElementTree as ET
BASE=Path(__file__).resolve().parent
def read(path):return json.loads((BASE/path).read_text(encoding='utf-8'))
def main():
    before=read('reports/baseline.json');after=read('reports/after_pilot_01.json');run=read('runs/pilot_01/run.json');summary=read('runs/pilot_01/summary.json');audit=read('reports/data_audit.json');security_before=read('reports/security_baseline.json');security_after=read('reports/security_after.json')
    records=[json.loads(l) for l in (BASE/'runs/pilot_01/metrics.jsonl').read_text().splitlines()]
    selected=[r for r in records if r.get('selected')][-1]
    assert before['dataset_sha256']==after['dataset_sha256']
    assert before['generation']==after['generation']
    assert before['parameters']==after['parameters']
    assert [p['id'] for p in before['probes']]==[p['id'] for p in after['probes']]
    domains=[{'domain':d,'before':v['loss'],'after':after['loss']['domains'][d]['loss']} for d,v in before['loss']['domains'].items()]
    root=ET.parse(BASE/'reports/pytest.xml').getroot();suites=list(root.iter('testsuite'));tests=sum(int(s.get('tests',0)) for s in suites);failures=sum(int(s.get('failures',0))+int(s.get('errors',0)) for s in suites)
    result={'available':True,'parameters':20587008,'architecture_changed':False,'source_sha256':before['sha256'],'pilot_checkpoint_sha256':after['sha256'],'selected_step':selected['step'],'completed_steps':summary['completed_step'],'stop_reason':summary['stop_reason'],'stop_note':'Early-stopping patience and max_steps were both reached at step 160; no updates beyond step 160 were run.','validation':{'before':run['baseline']['macro_loss'],'after':selected['validation']['macro_loss']},'test':{'before':before['loss']['macro_loss'],'after':after['loss']['macro_loss'],'records':sum(x['records'] for x in before['loss']['domains'].values()),'sha256':before['dataset_sha256']},'domains':domains,'math':{'before':before['math_numeric_exact'],'after':after['math_numeric_exact'],'source':'raw model generation; no SOLVE tool/guard'},'legacy_validation':{'before':before['legacy']['all_token_loss'],'after':after['legacy']['all_token_loss'],'note':before['legacy']['note']},'training':{'seconds':summary['elapsed_seconds'],'peak_allocated_vram_mib':summary['peak_vram_bytes']/2**20,'input_tokens':sum(r['input_tokens'] for r in records),'answer_tokens':sum(r['answer_tokens'] for r in records),'mean_update_tokens_per_second':sum(r['input_tokens'] for r in records)/sum(r['train_seconds'] for r in records),'precision':run['precision'],'gpu':run['gpu']},'security':{'guard_before':security_before['guard']['passed'],'guard_after':security_after['guard']['passed'],'guard_total':security_after['guard']['total'],'api_before':security_before['api']['passed'],'api_after':security_after['api']['passed'],'api_total':security_after['api']['total']},'tests':{'total':tests,'failed':failures},'limitations':['Free chat answers frequently remain incoherent or irrelevant.','0/12 exact arithmetic answers before and after.','Legacy distribution loss regressed. Original remains default.','Synthetic pilot: 976 train / 115 validation / 78 test records. Not a broad pretraining corpus.','Small curated security suite: no comprehensive safety guarantee.','Test was used once for final comparison, not checkpoint selection.','Checkpoint historical data provenance before the supplied package is unknown.']}
    (BASE/'reports/comparison.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8')
    lines=['# Neral / Helios – ausgeführter Entwicklungsstand','', 'Grundlage ist ausschließlich dein übergebener Neral-Checkpoint. Keine fremden Modellgewichte wurden geladen. Modell, Konfiguration und Byte-Tokenizer sind gegenüber dem Archiv unverändert.','', '## Prüfung des Originals',f'- Exakt **20.587.008** trainierbare Parameter; gebundene Embedding-/Ausgabegewichte.',f'- Original-SHA-256: `{before["sha256"]}`. Striktes Laden mit `weights_only=True`; alle Gewichte endlich.', '- Alle fünf Dateien des äußeren Manifests stimmen mit Größe und SHA-256 überein. Beide enthaltenen Checkpoints sind identisch.',f'- Daten: {audit["corpus_documents"]:,} Zeilen, nur {audit["unique_exact"]:,} exakt verschiedene Texte. {audit["duplicate_fraction"]:.2%} sind zusätzliche Wiederholungen.',f'- Keine exakte Train/Val-Überschneidung, aber {audit["normalized_train_val_overlap"]} gemeinsame normalisierte Texte; dadurch {audit["val_docs_normalized_seen_in_train"]:,} von {audit["val_documents"]:,} Validierungszeilen auch im Training enthalten.','', '## Tatsächlich ausgeführtes Training',f'- RTX 4070, PyTorch {run["torch"]}, {run["precision"]}, unveränderte Architektur.', '- 976 deduplizierte Trainingsbeispiele; 115 neue Validierungs- und 78 Testbeispiele. Eigenständig verfasste Beispiele plus überprüfte Rechen-/Code-Generatoren. Originaldaten nur als dedupliziertes Replay.', '- Domänenbalanciertes Sampling; Loss nur auf Antwort-Token. Diese Metrik ist nicht direkt mit dem alten All-Token-Loss vergleichbar.',f'- {summary["completed_step"]} Updates, {summary["elapsed_seconds"]:.2f} Sekunden gemessene Trainingsschleife, {result["training"]["peak_allocated_vram_mib"]:.1f} MiB maximal von PyTorch allokierter VRAM (nicht gesamter GPU-Speicher).',f'- Bester Checkpoint: Schritt {selected["step"]}. Vier spätere Prüfungen ohne Verbesserung. Stop-Regel und maximales Budget wurden beide bei Schritt 160 erreicht.',f'- Validierung (Macro-Antwort-Loss): **{result["validation"]["before"]:.4f} → {result["validation"]["after"]:.4f}**.', '', '## Eingefrorener Testvergleich','', '| Bereich | Original Loss | Pilot Loss |','|---|---:|---:|']
    lines += [f'| {r["domain"]} | {r["before"]:.4f} | {r["after"]:.4f} |' for r in domains]
    lines += ['',f'Test-Macro-Loss: **{result["test"]["before"]:.4f} → {result["test"]["after"]:.4f}**. Referenzantworten wurden mit identischen Verfahren ausgewertet. Niedrigerer Loss ist kein Nachweis funktionierender freier Antworten.','',f'**Reine Modell-Mathematik: {result["math"]["before"]["correct"]}/12 → {result["math"]["after"]["correct"]}/12 korrekt.** Die gespeicherten freien Chat- und Coding-Antworten bleiben häufig unverständlich oder sachlich unpassend.',f'Der alte Verteilungs-Loss verschlechterte sich von **{result["legacy_validation"]["before"]:.4f} auf {result["legacy_validation"]["after"]:.4f}**. Deshalb ersetzt der Pilot den Originalcheckpoint nicht automatisch.','', '## Umgesetzte Verbesserungen', '- Neu: reproduzierbare Daten-Splits, Antwortmaskierung, Domänenmetriken, Baseline vor Training, Checkpoint-Auswahl mit Guardrails, Early-Stopping, atomare Checkpoints und gespeicherte RNG-/Optimizer-/Scaler-Zustände.', '- Unsichere `weights_only=False`-Aufrufe in Eval-/Generate-Helfern beseitigt. Checkpoint-Prüfsumme in der Browser-App verpflichtend.', '- API: JSON-Typen, endliche Zahlen, Kontext-/Antwortbudget, Cross-Site-Schutz, Anfragelimits, exklusiver GPU-Zugriff, Abbruch, striktere CSP ohne Inline-Skripte.',f'- Erweiterte Security-Regression: **{result["security"]["guard_before"]}/{result["security"]["guard_total"]} → {result["security"]["guard_after"]}/{result["security"]["guard_total"]}**; API-Probes **4/8 → 8/8**. Die neue Suite wurde auch zur Fehlerbehebung verwendet und ist kein unabhängiger Red-Team-Test.',f'- Gesamte automatisierte Suite: **{tests} Tests, {failures} Fehler**. Zusätzlich enthält ein SOLVE-Test 840 exakt geprüfte Rechenfälle.', '- Browser: lokale Chats, temporärer Modus, Verlaufssuche, Export, erneutes Testen, Abbruch, Farbschema, Parameter-/Hash-Anzeige, Original/Pilot-Umschaltung und echte Messwerttabelle.', '- SOLVE: begrenzter AST-Parser und exakte Bruchrechnung, kein eval/exec. Klar als Werkzeug markiert; keine behauptete Modellfähigkeit.', '- Codeprüfung: Python-Syntax und wenige typische statische Muster, ohne den eingereichten Code auszuführen. Keine allgemeine Korrektheits- oder Sicherheitsgarantie.','', '## Grenzen und nächste sinnvolle Arbeit', 'Dieser Pilot verbessert die Mess- und Sicherheitsgrundlage, macht Neral aber noch nicht zu einem allgemein nützlichen Sprachmodell. Mehr Schritte auf diesen wenigen Beispielen sind aufgrund der gemessenen Überanpassung nicht sinnvoll. Der nächste substanzielle Schritt ist ein deutlich breiterer, lizenzgeprüfter Sprach-/Code-Korpus mit unabhängigen Aufgabenfamilien, bevor ein weiterer Lauf angesetzt wird. Architekturvergrößerung und fremde Gewichte sind nicht Bestandteil dieser Änderung.', '', '## Start', 'Doppelklicke `START_NERAL.bat`. Die lokale Testoberfläche ist unter `http://127.0.0.1:9680` erreichbar. Standardmäßig wird das Original geladen; den Pilot wählst du bewusst unter „Modell & Messwerte“.', '', '## Belege', '`reports/source_inventory.json`, `reports/data_audit.json`, `reports/baseline.json`, `reports/after_pilot_01.json`, `reports/security_baseline.json`, `reports/security_after.json`, `reports/pytest.xml`, `runs/pilot_01/run.json`, `runs/pilot_01/metrics.jsonl`, `runs/pilot_01/summary.json`.']
    (BASE/'ERGEBNISSE.md').write_text('\n'.join(lines)+'\n',encoding='utf-8');print(json.dumps(result,ensure_ascii=True,indent=2))
if __name__=='__main__':main()
